using System;using System.IO;using System.Reflection;using System.Threading;using System.Linq;using System.Drawing;using System.Collections.Generic;using Newtonsoft.Json;using WF=System.Windows.Forms;
namespace PhotoTutor {
 internal static class PreviewLayoutChecks {
  internal static int Run(string folder){Directory.CreateDirectory(folder);Settings.IsolatedTestRoot=Path.Combine(folder,"isolated");Entry.OfflineUiTesting=true;Entry.DemoCamera=true;CameraSession.EnumerateForTest=()=>Array.Empty<CameraDevice>();var rows=new List<object>();int failed=0;
   foreach(var size in new[]{new Size(1280,720),new Size(1366,768),new Size(1920,1080)}){try{using(var form=new TutorForm()){form.ShowInTaskbar=false;form.StartPosition=WF.FormStartPosition.Manual;form.Location=new Point(-12000,-12000);form.Show();form.Size=size;var split=(WF.SplitContainer)typeof(TutorForm).GetField("split",BindingFlags.Instance|BindingFlags.NonPublic)!.GetValue(form)!;split.SplitterDistance=(int)(split.Width*.44);var view=(WF.Control)typeof(TutorForm).GetField("picture",BindingFlags.Instance|BindingFlags.NonPublic)!.GetValue(form)!;var live=typeof(TutorForm).GetField("live",BindingFlags.Instance|BindingFlags.NonPublic)!;var end=DateTime.UtcNow.AddSeconds(5);while(live.GetValue(form)==null&&DateTime.UtcNow<end){WF.Application.DoEvents();Thread.Sleep(20);}form.PerformLayout();WF.Application.DoEvents();bool pass=live.GetValue(form)!=null&&view.ClientSize.Width>=200&&view.ClientSize.Height>=120;if(!pass)failed++;rows.Add(new{screen=size.ToString(),passed=pass,previewWidth=view.Width,previewHeight=view.Height,withoutClickingPhoto=live.GetValue(form)!=null});using(var bitmap=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(bitmap,new Rectangle(Point.Empty,form.Size));bitmap.Save(Path.Combine(folder,$"preview_{size.Width}x{size.Height}.png"));}form.Close();while(CameraSession.IsActive&&DateTime.UtcNow<end){WF.Application.DoEvents();Thread.Sleep(20);}}}catch(Exception e){failed++;rows.Add(new{screen=size.ToString(),passed=false,error=e.ToString()});}}
   CameraSession.EnumerateForTest=null;Entry.DemoCamera=Entry.OfflineUiTesting=false;File.WriteAllText(Path.Combine(folder,"预览可见性.json"),JsonConvert.SerializeObject(new{failed,checks=rows,physicalCamera=false},Formatting.Indented));return failed==0?0:1;
  }
 }
}
